from itertools import combinations

yields = [4, 2, 7, 1, 3, 6, 5]
n = 7

best_total = -1
best_pattern = None

for r in range(0, n + 1):
    for combo in combinations(range(1, n + 1), r):
        valid = True
        for i in range(len(combo) - 1):
            if combo[i + 1] - combo[i] == 1:
                valid = False
                break
        if not valid:
            continue
        total = sum(yields[c - 1] for c in combo)
        pattern = [0] * n
        for c in combo:
            pattern[c - 1] = 1
        if total > best_total:
            best_total = total
            best_pattern = pattern
        elif total == best_total:
            if pattern < best_pattern:
                best_pattern = pattern

rows = [str(i + 1) for i, v in enumerate(best_pattern) if v == 1]
print(f"Max baskets: {best_total}")
print("Rows: " + " ".join(rows))
print("Pattern: " + " ".join(str(x) for x in best_pattern))

import sys

def main():
    arrivals = {
        1: [(1, 20)],
        2: [(4, 40)],
        3: [(1, 10)],
        4: [(3, 30)],
        5: [(2, 21)],
        6: [(4, 42)],
        7: [(1, 10)],
        8: [(4, 42)],
    }

    # Build per-station event lists
    stations = {1: [], 2: [], 3: [], 4: []}
    for runner, lst in arrivals.items():
        for station, t in lst:
            stations[station].append((t, runner))

    finish = {}
    for station, events in stations.items():
        # sort by arrival time, then runner number
        events.sort(key=lambda x: (x[0], x[1]))
        free_at = 0
        for t, runner in events:
            start = max(t, free_at)
            end = start + 2
            free_at = end
            finish[runner] = (station, end)

    for runner in range(1, 9):
        if runner in finish:
            station, end = finish[runner]
            print(f"Runner {runner}: station {station} finishes at minute {end}")

if __name__ == "__main__":
    main()

from itertools import product

def moves_to_pos(moves, start=(1,1)):
    r, c = start
    for m in moves:
        if m == 'R':
            c += 1
        else:
            r += 1
    return (r, c)

def visits(moves, target):
    r, c = 1, 1
    if (r, c) == target:
        return True
    for m in moves:
        if m == 'R':
            c += 1
        else:
            r += 1
        if (r, c) == target:
            return True
    return False

