import sys

def main():
    try:
        with open('entries.txt', 'r') as f:
            lines = f.readlines()
    except FileNotFoundError:
        lines = []

    accepted = 0
    rejected = 0
    total_rating = 0
    total_games = 0
    total_points = 0.0
    top_name = None
    top_points = -1.0

    for line in lines:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 4:
            rejected += 1
            continue
        name, rating_s, games_s, points_s = parts
        try:
            rating = int(rating_s)
            games = int(games_s)
            points = float(points_s)
        except ValueError:
            rejected += 1
            continue

        valid = True
        if not (800 <= rating <= 3000):
            valid = False
        if games < 0:
            valid = False
        if not (0 <= points <= games):
            valid = False

        if valid:
            accepted += 1
            total_rating += rating
            total_games += games
            total_points += points
            if top_name is None or points > top_points:
                top_name = name
                top_points = points
        else:
            rejected += 1

    print(f"Accepted entries: {accepted}")
    print(f"Rejected entries: {rejected}")
    if accepted > 0:
        avg = round(total_rating / accepted)
        print(f"Average rating: {avg}")
    else:
        print("Average rating: 0")
    print(f"Total games: {total_games}")
    print(f"Total points: {total_points:.1f}")
    if top_name is None:
        print("Top scorer: NONE")
    else:
        print(f"Top scorer: {top_name}")

if __name__ == "__main__":
    main()

from itertools import product

total = 0
a_period1 = 0
no_consecutive = 0

for assignment in product('ABC', repeat=4):
    counts = {t: assignment.count(t) for t in 'ABC'}
    if counts['A'] > 2 or counts['B'] > 3 or counts['C'] > 2:
        continue
    if counts['A'] < 1 or counts['B'] < 1 or counts['C'] < 1:
        continue
    total += 1
    if assignment[0] == 'A':
        a_period1 += 1
    if all(assignment[i] != assignment[i+1] for i in range(3)):
        no_consecutive += 1

print(f"TotalValid: {total}")
print(f"APeriod1: {a_period1}")
print(f"NoConsecutive: {no_consecutive}")

from itertools import permutations

results = []
for p in permutations('ABCD'):
    desk = {1: p[0], 2: p[1], 3: p[2], 4: p[3]}
    if desk[2] != 'A' and desk[3] != 'A':
        continue
    if desk[1] == 'D':
        continue
    if abs(list(desk.values()).index('B') - list(desk.values()).index('C')) == 1:
        continue
    results.append(''.join(p))

results.sort()
for r in results:
    print(r)
print(f"Count: {len(results)}")

